"""Summarize log lines as (level, message) pairs."""


def summarize(lines):
    out = []
    for line in lines:
        if not line.strip():
            continue
        parts = line.split(' ', 1)
        out.append((parts[0], parts[1] if len(parts) > 1 else ''))
    return out

from summarize_log import summarize


def test_regression_only_blank_lines():
    assert summarize(["", "   "]) == []
